SELECT p.gender, s.admission_type_code, AVG(s.los) AS average_los, STDDEV(s.los) AS standard_deviation_los, COUNT(CASE WHEN s.los <= 7 THEN 1 END) * 100.0 / NULLIF(COUNT(s.los), 0) AS percentage_of_patients_with_los_less_than_or_equal_to_7_days FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.subject_id = s.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM CURRENT_DATE) - p.birth_date >= 72 AND EXTRACT(YEAR FROM a.admittime) <= EXTRACT(YEAR FROM CURRENT_DATE) - 7 AND s.dischtime IS NOT NULL AND (s.dischtime - s.intime) <= 7 AND (s.dischtime - s.intime) >= 0 AND a.admission_type_code = 'SURGICAL' GROUP BY p.gender, s.admission_type_code ORDER BY p.gender, s.admission_type_code NULLS LAST;